def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - we have a complete field
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check for doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == len(line):
                            fields.append(''.join(field))
                            break
                        elif line[i] == ',':
                            fields.append(''.join(field))
                            i += 1
                            # Check if there's another field after comma
                            if i == len(line):
                                fields.append('')
                            break
                        else:
                            # Invalid: closing quote not followed by comma or EOL
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is invalid
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < len(line):
                # We hit a comma
                i += 1
                # Check if there's another field after comma
                if i == len(line):
                    fields.append('')

    return fields

